import static org.junit.Assert.*;
import java.util.Locale;

public class AgentBRT_Lang_40_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(new Locale("tr", "TR")); // Set Turkish locale
            String str = "istanbul";
            String searchStr = "I";
            // This should return true, but due to locale issues, it may return false
            assertTrue(StringUtils.containsIgnoreCase(str, searchStr));
